import java.util.Scanner;

public class Variant1 {
    static int MOD = 998244353;
    static long[] fact;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        long pk = scanner.nextLong();

        if (pk > N - 1) {
            System.out.println(0);
        } else {
            int k = (int) pk;
            fact = new long[N + 1];
            fact[0] = 1;
            for (int i = 1; i <= N; i++) {
                fact[i] = (i * fact[i - 1]) % MOD;
            }
            long ans = 0;
            int dir = 1;
            int c = N - k;
            for (int i = c; i >= 0; i--) {
                long dif = (choose(c, i) * power(i, N)) % MOD;
                dif = dir * dif;
                ans = (ans + dif + MOD) % MOD;
                dir = -dir;
            }
            ans = (ans * choose(N, c)) % MOD;
            if (k > 0) {
                ans = (2 * ans) % MOD;
            }
            System.out.println(ans);
        }
        scanner.close();
    }

    static long choose(int a, int b) {
        long res = (fact[a] * inv((fact[b] * fact[a - b]) % MOD)) % MOD;
        return res;
    }

    static long power(long x, int y) {
        long res = 1;
        while (y > 0) {
            if (y % 2 == 1) res = (res * x) % MOD;
            x = (x * x) % MOD;
            y /= 2;
        }
        return res % MOD;
    }

    static long inv(long a) {
        return power(a, MOD - 2);
    }
}
